			&lt;p style=&quot;text-align: center;&quot;&gt;&lt;strong&gt;स्तंभ A&lt;/strong&gt;&lt;/p&gt;
			&lt;/td&gt;
			&lt;td&gt;
			&lt;p style=&quot;text-align: center;&quot;&gt;&lt;strong&gt;स्तंभ B&lt;/strong&gt;&lt;/p&gt;
			&lt;/td&gt;
		&lt;/tr&gt;
		&lt;tr&gt;
			&lt;td&gt;
			&lt;p&gt;i. कोशिका भित्ति&lt;/p&gt;
			&lt;/td&gt;
			&lt;td&gt;
			&lt;p&gt;B.&amp;nbsp; कोशिका को सहारा देता है।&lt;/p&gt;
			&lt;/td&gt;
		&lt;/tr&gt;
		&lt;tr&gt;
			&lt;td&gt;
			&lt;p&gt;ii. कोशिका झिल्ली&lt;/p&gt;
			&lt;/td&gt;
			&lt;td&gt;
			&lt;p&gt;C. यह नियंत्रित करता है कि कोशिका के अंदर और बाहर क्या जा रहा है।&lt;/p&gt;
			&lt;/td&gt;
		&lt;/tr&gt;
		&lt;tr&gt;
			&lt;td&gt;
			&lt;p&gt;iii. कोशिका द्रव्य&lt;/p&gt;
			&lt;/td&gt;
			&lt;td&gt;
			&lt;p&gt;D. इसमें कोशिका अभिक्रिया होती हैं।&lt;/p&gt;
			&lt;/td&gt;
		&lt;/tr&gt;
		&lt;tr&gt;
			&lt;td&gt;
			&lt;p&gt;iv. केंद्रक&lt;/p&gt;
			&lt;/td&gt;
			&lt;td&gt;
			&lt;p&gt;A. जो होता है उसे नियंत्रित करता है&lt;/p&gt;
			&lt;/td&gt;
		&lt;/tr&gt;
	&lt;/tbody&gt;
&lt;/table&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;कोशिका भित्ति&lt;/strong&gt;&lt;strong&gt;:&lt;/strong&gt;

	&lt;ul&gt;
		&lt;li&gt;पादप कोशिकाओं में,&lt;strong&gt; प्लाज्मा झिल्ली&lt;/strong&gt; के अलावा, एक और कठोर बाहरी आवरण होता है जिसे &lt;strong&gt;कोशिका भित्ति&lt;/strong&gt; कहते हैं। कोशिका भित्ति, प्लाज्मा झिल्ली के बाहर स्थित होती है। पादप कोशिका भित्ति मुख्य रूप से कोशिकारस से बनी होती है।&lt;/li&gt;
		&lt;li&gt;&lt;strong&gt;कोशिका भित्ति कोशिका को यांत्रिक सहारा प्रदान करती है।&lt;/strong&gt;&lt;strong&gt;&lt;strong&gt;​&lt;/strong&gt;&lt;/strong&gt;&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;span id=&quot;cke_bm_3688E&quot; style=&quot;display: none;&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;strong&gt;कोशिका झिल्ली&lt;/strong&gt;&lt;strong&gt;:&amp;nbsp;&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;यह कोशिका का सबसे बाहरी आवरण है जो कोशिका के पदार्थ को उसके बाहरी वातावरण से अलग करता है।&lt;/li&gt;
		&lt;li&gt;&lt;strong&gt;कोशिका झिल्ली कोशिका के अंदर और बाहर कुछ पदार्थों के प्रवेश और निकास की अनुमति देती है।&lt;/strong&gt;&lt;/li&gt;
		&lt;li&gt;यह कुछ अन्य पदार्थों की आवाजाही को भी रोकती है। इसलिए, कोशिका झिल्ली को &lt;strong&gt;चयनात्मक पारगम्य झिल्ली&lt;/strong&gt; कहा जाता है।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;कोशिका द्रव्य&lt;/strong&gt;&lt;strong&gt;:&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;कोशिका द्रव्य प्लाज्मा झिल्ली के अंदर द्रव सामग्री है।&lt;/li&gt;
		&lt;li&gt;&lt;strong&gt;यह कोशिकीय क्रियाकलापों का स्थल है अर्थात् इसमें कोशिका अभिक्रियाएँ होती हैं।&lt;/strong&gt;&lt;/li&gt;
		&lt;li&gt;इसमें कई विशिष्ट कोशिका अंगक भी होते हैं। इनमें से प्रत्येक अंगक कोशिका के लिए एक विशिष्ट कार्य करते हैं।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;केंद्रक&lt;/strong&gt;:
	&lt;ul&gt;
		&lt;li&gt;केंद्रक को कोशिका का मस्तिष्क कहा जाता है क्योंकि&lt;strong&gt; यह सभी कोशिकीय चयापचय को नियंत्रित करता है और कोशिका की आनुवंशिक जानकारी को संलग्न करता है।&lt;/strong&gt;&lt;/li&gt;
		&lt;li&gt;केंद्रक में दो परतों वाला आवरण होता है जिसे&lt;strong&gt; &lt;/strong&gt;&lt;strong&gt;केन्द्रकीय&lt;/strong&gt;&lt;strong&gt; झिल्ली&lt;/strong&gt; कहते हैं।&lt;/li&gt;
		&lt;li&gt;केन्द्रकीय झिल्ली में छिद्र होते हैं जो पदार्थ को केंद्रक के अंदर से उसके बाहर, अर्थात् कोशिका द्रव्य में स्थानांतरित करने की अनुमति देते हैं।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

