&lt;p style=&quot;&quot;&gt;&lt;span id=&quot;docs-internal-guid-b4b10ddd-7fff-c172-0fc4-2a3e35ec9a32&quot;&gt;&lt;span style=&quot;background-color: transparent; font-weight: 700; font-variant-numeric: normal; font-variant-east-asian: normal; vertical-align: baseline; white-space: pre-wrap;&quot;&gt;Given data:&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;a&lt;span style=&quot;line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;+ b&lt;span style=&quot;line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;+ 49c&lt;span style=&quot;line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;+ 18 = 2(b +&amp;nbsp;28c - a)&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&lt;span id=&quot;docs-internal-guid-5b4aa901-7fff-7e4a-84b5-bd8bd90727a2&quot;&gt;&lt;span style=&quot;background-color: transparent; font-weight: 700; font-variant-numeric: normal; font-variant-east-asian: normal; vertical-align: baseline; white-space: pre-wrap;&quot;&gt;Formula Used:&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

