&lt;p style=&quot;&quot;&gt;2)&amp;nbsp;(a&amp;nbsp;- b)&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em;font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;= a&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em;font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;+ b&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em;font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;- 2ab&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&lt;span id=&quot;docs-internal-guid-d5801ab0-7fff-6ed9-ee0e-05c93856db25&quot;&gt;&lt;span style=&quot;background-color: transparent; font-weight: 700; font-variant-numeric: normal; font-variant-east-asian: normal; vertical-align: baseline; white-space: pre-wrap;&quot;&gt;Calculations:&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;According to question,&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;a&lt;span style=&quot;line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;+ b&lt;span style=&quot;line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;+ 49c&lt;span style=&quot;line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;+ 18 = 2(b +&amp;nbsp;28c - a)&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&amp;rArr; a&lt;span style=&quot;line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;+ b&lt;span style=&quot;line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;+ 49c&lt;span style=&quot;line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;+ 18 = 2b +&amp;nbsp;56c -2a&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&amp;rArr; a&lt;span style=&quot;line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;+ b&lt;span style=&quot;line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&amp;nbsp;&lt;/span&gt;&amp;nbsp;+ 49c&lt;span style=&quot;line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;+ 18 - 2b -&amp;nbsp;56c +&amp;nbsp;2a = 0&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&amp;rArr; (a&lt;span style=&quot;line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&amp;nbsp;&lt;/span&gt;+ 2a + 1 ) + (b&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em;font-size:10.5px;&quot;&gt;2&amp;nbsp;&lt;/span&gt;- 2b + 1) + (7c)&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em;font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;-&amp;nbsp;56c + 16&amp;nbsp;= 0&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&amp;rArr;&amp;nbsp;(a + 1)&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em;font-size:10.5px;&quot;&gt;2&amp;nbsp;&lt;/span&gt;+ (b - 1)&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em;font-size:10.5px;&quot;&gt;2&amp;nbsp;&lt;/span&gt;+ {(7c)&lt;span style=&quot;line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;-&amp;nbsp;56c&amp;nbsp;+ 4&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em;font-size:10.5px;&quot;&gt;2&lt;/span&gt;} = 0&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&amp;rArr;&amp;nbsp;(a + 1)&lt;span style=&quot;line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&amp;nbsp;&lt;/span&gt;+ (b - 1)&lt;span style=&quot;line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&amp;nbsp;&lt;/span&gt;&amp;nbsp;+ (7c&lt;span style=&quot;font-size: 10.5px;&quot;&gt;&amp;nbsp;-&lt;/span&gt;&amp;nbsp;4)&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em;font-size:10.5px;&quot;&gt;2&amp;nbsp;&lt;/span&gt;= 0&amp;nbsp; &amp;nbsp; &amp;nbsp; ----(1) (from formula 1 and 2)&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;Now In equation 1, In&amp;nbsp;order it to be = 0 all the entities must be 0&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&amp;there4;&amp;nbsp;(a + 1)&lt;span style=&quot;line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&amp;nbsp;&lt;/span&gt;= 0&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&amp;rArr;&amp;nbsp;(a + 1) = 0&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&amp;rArr; a = -1&amp;nbsp; &amp;nbsp; &amp;nbsp; ----(2)&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;Again,&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;(b - 1)&lt;span style=&quot;line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;= 0&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&amp;rArr;&amp;nbsp;(b - 1) = 0&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&amp;rArr; b = 1&amp;nbsp; &amp;nbsp; &amp;nbsp; ----(3)&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;Again,&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;(7c&lt;span style=&quot;font-size: 10.5px;&quot;&gt;&amp;nbsp;-&lt;/span&gt;&amp;nbsp;4)&lt;span style=&quot;line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&amp;nbsp;&lt;/span&gt;= 0&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&amp;rArr;&amp;nbsp;(7c&lt;span style=&quot;line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;&amp;nbsp;&lt;/span&gt;- 4) = 0&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&amp;rArr; 7c =&amp;nbsp;4&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&amp;nbsp;&amp;rArr; c =&amp;nbsp;&lt;span class=&quot;math-tex&quot;&gt;\(4\over7 \)&lt;/span&gt; &amp;nbsp; &amp;nbsp; ----(4)&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;As per question,&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;(2a - b + 7c) = (2 &amp;times; -1) - 1 + 7&amp;nbsp;&amp;times; &lt;span class=&quot;math-tex&quot;&gt;\(4\over7 \)&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&amp;rArr;&amp;nbsp;&amp;nbsp;-2&amp;nbsp;- 1 + 4&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&amp;rArr; 1&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;there4; The value of (2a - b + 7c) is 1.&lt;/span&gt;&lt;/p&gt;

hn.value:
&lt;p style=&quot;&quot;&gt;&lt;span id=&quot;docs-internal-guid-b4b10ddd-7fff-c172-0fc4-2a3e35ec9a32&quot;&gt;&lt;span style=&quot;background-color: transparent; font-weight: 700; font-variant-numeric: normal; font-variant-east-asian: normal; vertical-align: baseline; white-space: pre-wrap;&quot;&gt;दिए गए आंकड़े है:&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;a&lt;span style=&quot;line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;+ b&lt;span style=&quot;line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;+ 49c&lt;span style=&quot;line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;+ 18 = 2(b +&amp;nbsp;28c - a)&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&lt;span id=&quot;docs-internal-guid-5b4aa901-7fff-7e4a-84b5-bd8bd90727a2&quot;&gt;&lt;span style=&quot;background-color: transparent; font-weight: 700; font-variant-numeric: normal; font-variant-east-asian: normal; vertical-align: baseline; white-space: pre-wrap;&quot;&gt;प्रयुक्त सूत्र:&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;1)&amp;nbsp;(a + b)&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em;font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;= a&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em;font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;+ b&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em;font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;+ 2ab&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;2)&amp;nbsp;(a&amp;nbsp;- b)&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em;font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;= a&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em;font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;+ b&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em;font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;- 2ab&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&lt;span id=&quot;docs-internal-guid-d5801ab0-7fff-6ed9-ee0e-05c93856db25&quot;&gt;&lt;span style=&quot;background-color: transparent; font-weight: 700; font-variant-numeric: normal; font-variant-east-asian: normal; vertical-align: baseline; white-space: pre-wrap;&quot;&gt;गणना:&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;प्रश्न के अनुसार,&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;a&lt;span style=&quot;line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;+ b&lt;span style=&quot;line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;+ 49c&lt;span style=&quot;line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;+ 18 = 2(b +&amp;nbsp;28c - a)&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&amp;rArr; a&lt;span style=&quot;line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;+ b&lt;span style=&quot;line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;+ 49c&lt;span style=&quot;line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;+ 18 = 2b +&amp;nbsp;56c -2a&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&amp;rArr; a&lt;span style=&quot;line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;+ b&lt;span style=&quot;line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&amp;nbsp;&lt;/span&gt;&amp;nbsp;+ 49c&lt;span style=&quot;line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;+ 18 - 2b -&amp;nbsp;56c +&amp;nbsp;2a = 0&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&amp;rArr; (a&lt;span style=&quot;line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&amp;nbsp;&lt;/span&gt;+ 2a + 1 ) + (b&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em;font-size:10.5px;&quot;&gt;2&amp;nbsp;&lt;/span&gt;- 2b + 1) + (7c)&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em;font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;-&amp;nbsp;56c + 16&amp;nbsp;= 0&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&amp;rArr;&amp;nbsp;(a + 1)&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em;font-size:10.5px;&quot;&gt;2&amp;nbsp;&lt;/span&gt;+ (b - 1)&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em;font-size:10.5px;&quot;&gt;2&amp;nbsp;&lt;/span&gt;+ {(7c)&lt;span style=&quot;line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;-&amp;nbsp;56c&amp;nbsp;+ 4&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em;font-size:10.5px;&quot;&gt;2&lt;/span&gt;} = 0&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&amp;rArr;&amp;nbsp;(a + 1)&lt;span style=&quot;line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&amp;nbsp;&lt;/span&gt;+ (b - 1)&lt;span style=&quot;line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&amp;nbsp;&lt;/span&gt;&amp;nbsp;+ (7c&lt;span style=&quot;font-size: 10.5px;&quot;&gt;&amp;nbsp;-&lt;/span&gt;&amp;nbsp;4)&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em;font-size:10.5px;&quot;&gt;2&amp;nbsp;&lt;/span&gt;= 0&amp;nbsp; &amp;nbsp; &amp;nbsp; ----(1) (सूत्र 1 और 2 से)&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;अब समीकरण 1 में, इसे 0 के बराबर होने के लिए सभी इकाइयों को 0 होना चाहिए।&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&amp;there4;&amp;nbsp;(a + 1)&lt;span style=&quot;line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&amp;nbsp;&lt;/span&gt;= 0&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&amp;rArr;&amp;nbsp;(a + 1) = 0&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&amp;rArr; a = -1&amp;nbsp; &amp;nbsp; &amp;nbsp; ----(2)&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;पुनः,&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;(b - 1)&lt;span style=&quot;line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;= 0&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&amp;rArr;&amp;nbsp;(b - 1) = 0&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&amp;rArr; b = 1&amp;nbsp; &amp;nbsp; &amp;nbsp; ----(3)&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;पुनः,&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;(7c&lt;span style=&quot;font-size: 10.5px;&quot;&gt;&amp;nbsp;-&lt;/span&gt;&amp;nbsp;4)&lt;span style=&quot;line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&amp;nbsp;&lt;/span&gt;= 0&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&amp;rArr;&amp;nbsp;(7c&lt;span style=&quot;line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;&amp;nbsp;&lt;/span&gt;- 4) = 0&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&amp;rArr; 7c =&amp;nbsp;4&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&amp;nbsp;&amp;rArr; c =&amp;nbsp;&lt;span class=&quot;math-tex&quot;&gt;\(4\over7 \)&lt;/span&gt; &amp;nbsp; &amp;nbsp; ----(4)&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;प्रश्न के अनुसार,&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;(2a - b + 7c) = (2 &amp;times; -1) - 1 + 7&amp;nbsp;&amp;times; &lt;span class=&quot;math-tex&quot;&gt;\(4\over7 \)&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&amp;rArr;&amp;nbsp;&amp;nbsp;-2&amp;nbsp;- 1 + 4&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&amp;rArr; 1&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;there4; (2a - b + 7c) का मान 1 है।&lt;/span&gt;&lt;/p&gt;

en.value:
&lt;p&gt;&lt;strong&gt;Given data:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;Marked Price = Rs 1800&lt;/p&gt;

&lt;p&gt;Discount = 15%&lt;/p&gt;

&lt;p&gt;Extra discount for paying in cash = 8%&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Formula:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;Effective discount = d&lt;sub&gt;1&lt;/sub&gt;&lt;sub&gt;&amp;nbsp;&lt;/sub&gt;+ d&lt;sub&gt;2&lt;/sub&gt;&amp;nbsp;&amp;ndash;&amp;nbsp;&lt;span class=&quot;math-tex&quot;&gt;\(d_1 × d_2 \over 100\)&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;Where d1 and d2 are discount and extra discounts respectively.&lt;/p&gt;

&lt;p&gt;SP = MP (1 &amp;ndash; Effective discount%)&lt;/p&gt;

&lt;p&gt;Where SP and MP are Selling Price and Marked Price.&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Calculations:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;Effective discount = 15 + 8 &amp;ndash;&amp;nbsp;&lt;span class=&quot;math-tex&quot;&gt;\(15 \times 8 \over 100\)&lt;/span&gt; = 23 &amp;ndash; 1.2 = 21.8 %&lt;/p&gt;

&lt;p&gt;SP = 18&amp;nbsp;&amp;times;&amp;nbsp; (1 - 0.218) = Rs 1408 (rounded off to the nearest rupee).&lt;/p&gt;

&lt;p&gt;&amp;there4; &lt;strong&gt;The cost paid by dealer&amp;nbsp;to the manufacturer is Rs 1408.&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;

hn.value:
&lt;p&gt;&lt;span style=&quot;font-weight: 700; &quot;&gt;दिए गए आंकड़े हैं:​&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;अंकित मूल्य = 1800 रुपये&lt;/p&gt;

&lt;p&gt;छूट = 15%&lt;/p&gt;

&lt;p&gt;नकद भुगतान करने पर अतिरिक्त छूट = 8%&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;सूत्र:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;प्रभावी छूट = d1 + d2 &amp;ndash;&amp;nbsp;&lt;span class=&quot;math-tex&quot;&gt;\(d_1 × d_2 \over 100\)&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;जहां d1 और d2 क्रमशः छूट और अतिरिक्त छूट हैं।&lt;/p&gt;

&lt;p&gt;SP = MP (1 &amp;ndash; प्रभावी छूट%)&lt;/p&gt;

&lt;p&gt;जहां SP और MP विक्रय मूल्य और अंकित मूल्य हैं।&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;गणना:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;प्रभावी छूट = 15 + 8 &amp;ndash;&amp;nbsp;&lt;span class=&quot;math-tex&quot;&gt;\(15 \times 8 \over 100\)&lt;/span&gt; = 23 &amp;ndash; 1.2 = 21.8 %&lt;/p&gt;

&lt;p&gt;SP = 18&amp;nbsp;&amp;times;&amp;nbsp; (1 - 0.218) = 1408 रुपये (निकटतम रुपये में पूर्णांकित)&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&amp;there4; व्यापारी&amp;nbsp;द्वारा निर्माता को भुगतान किया गया मूल्य 1408 रुपये है।&lt;/strong&gt;&lt;/p&gt;

en.value:
&lt;p&gt;&lt;strong&gt;Given:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;A reduction of 20% in the price of bananas enables a customer to buy 6 more bananas for ₹80&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Calculation:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;Let the C.P of each banana be x&lt;/p&gt;

&lt;p&gt;Total number of bananas in &lt;span style=&quot;&quot;&gt;₹&lt;/span&gt; 80 = 80/x&lt;/p&gt;

&lt;p&gt;New price = x &amp;ndash;&lt;span style=&quot;&quot;&gt;&amp;nbsp;x&amp;nbsp;&amp;times;&amp;nbsp;&lt;/span&gt;(20/100)&lt;/p&gt;

&lt;p&gt;&amp;rArr; (100 - 20)x/100&lt;/p&gt;

&lt;p&gt;&amp;rArr; 80x/100 or 4x/5&lt;/p&gt;

&lt;p&gt;New number of bananas in &lt;span style=&quot;&quot;&gt;₹&lt;/span&gt;80 =&amp;nbsp;&lt;span style=&quot;&quot;&gt;80/(4x/5)&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&amp;rArr; 80/(4x/5)&lt;/p&gt;

&lt;p&gt;&amp;rArr; 100/x&lt;/p&gt;

&lt;p&gt;&amp;rArr; (100/x) &amp;ndash; (80/x) = 6&amp;nbsp;&lt;/p&gt;

&lt;p&gt;&amp;rArr; 20/x = 6&amp;nbsp;&lt;/p&gt;

&lt;p&gt;&amp;rArr; x = 20/6&lt;/p&gt;

&lt;p&gt;New price of bananas = 20/6 &amp;times; 4/5&lt;/p&gt;

&lt;p&gt;&amp;rArr; 8/3&lt;/p&gt;

&lt;p&gt;The reduced price of bananas per dozen = (8/3)&amp;nbsp;&amp;times; 12&lt;/p&gt;

&lt;p&gt;&amp;rArr; 32&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;&amp;there4;&amp;nbsp;The reduced price of bananas per dozen (in ₹) is 32.&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/shortcut-trick-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Shortcut Trick&lt;/u&gt;&lt;/span&gt;&lt;strong&gt;&amp;nbsp;&lt;/strong&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;

&lt;p style=&quot;color: rgb(97, 106, 124); &quot;&gt;Let the original price of a banana be 5x, new price will be 4x(reduced by 20%)&lt;/p&gt;

&lt;p style=&quot;color: rgb(97, 106, 124); &quot;&gt;Now, according to the question,&lt;/p&gt;

&lt;p style=&quot;color: rgb(97, 106, 124); &quot;&gt;&amp;rArr;&amp;nbsp;&lt;span class=&quot;math-tex&quot;&gt;\(80\over 4x\)&lt;/span&gt;&amp;nbsp;-&amp;nbsp;&lt;span class=&quot;math-tex&quot;&gt;\(80\over 5x\)&lt;/span&gt;&amp;nbsp;= 6&lt;/p&gt;

&lt;p style=&quot;color: rgb(97, 106, 124); &quot;&gt;&amp;rArr;&amp;nbsp;&lt;span class=&quot;math-tex&quot;&gt;\({80 (5 - 4)}\over 4 \times 5 \times x\)&lt;/span&gt;&amp;nbsp;= 6&lt;/p&gt;

&lt;p style=&quot;color: rgb(97, 106, 124); &quot;&gt;&amp;rArr;&amp;nbsp;&lt;span class=&quot;math-tex&quot;&gt;\({80 (5 - 4)}\over 20 \times x\)&lt;/span&gt;&amp;nbsp;= 6&lt;/p&gt;

&lt;p style=&quot;color: rgb(97, 106, 124); &quot;&gt;&amp;rArr;&amp;nbsp;&lt;span class=&quot;math-tex&quot;&gt;\(4\over x\)&lt;/span&gt;&amp;nbsp;= 6&lt;/p&gt;

&lt;p style=&quot;color: rgb(97, 106, 124); &quot;&gt;&amp;rArr; x =&amp;nbsp;&lt;span class=&quot;math-tex&quot;&gt;\(2\over3\)&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;color: rgb(97, 106, 124); &quot;&gt;The new price of bananas is,&lt;/p&gt;

&lt;p style=&quot;color: rgb(97, 106, 124); &quot;&gt;&amp;rArr; 4x = 4&amp;nbsp;&amp;times;&lt;span class=&quot;math-tex&quot;&gt;\(2\over3\)&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;color: rgb(97, 106, 124); &quot;&gt;The price per dozen is&lt;/p&gt;

&lt;p style=&quot;color: rgb(97, 106, 124); &quot;&gt;&amp;rArr; 4&amp;nbsp;&amp;times;&amp;nbsp;&lt;span class=&quot;math-tex&quot;&gt;\(2\over3\)&lt;/span&gt;&amp;nbsp;&amp;times; 12 = 32&lt;/p&gt;

hn.value:
&lt;p&gt;&lt;span style=&quot;font-weight: 700; &quot;&gt;दिया गया है:&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;केलों के मूल्य में 20% की कमी से ग्राहक ₹80 में 6 और केले खरीद सकता है।&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;गणना:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;माना प्रत्येक केले का क्रय मूल्य x&amp;nbsp;है&lt;/p&gt;

&lt;p&gt;₹80 में केलों की कुल संख्या = 80/x&lt;/p&gt;

&lt;p&gt;नया मूल्य = x &amp;ndash;&lt;span style=&quot;&quot;&gt;&amp;nbsp;x&amp;nbsp;&amp;times;&amp;nbsp;&lt;/span&gt;(20/100)&lt;/p&gt;

&lt;p&gt;&amp;rArr; (100 - 20)x/100&lt;/p&gt;

&lt;p&gt;&amp;rArr; 80x/100 or 4x/5&lt;/p&gt;

&lt;p&gt;₹80 में केलों की नई संख्या =&amp;nbsp;&lt;span style=&quot;&quot;&gt;80/(4x/5)&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&amp;rArr; 80/(4x/5)&lt;/p&gt;

&lt;p&gt;&amp;rArr; 100/x&lt;/p&gt;

&lt;p&gt;&amp;rArr; (100/x) &amp;ndash; (80/x) = 6&lt;/p&gt;

&lt;p&gt;&amp;rArr; 20/x = 6&lt;/p&gt;

&lt;p&gt;&amp;rArr; x = 20/6&lt;/p&gt;

&lt;p&gt;केलों का नया मूल्य = 20/6 &amp;times; 4/5&lt;/p&gt;

&lt;p&gt;&amp;rArr; 8/3&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;प्रति दर्जन&amp;nbsp;&lt;/span&gt;केलों का घटा हुआ मूल्य&amp;nbsp;= (8/3)&amp;nbsp;&amp;times; 12&lt;/p&gt;

&lt;p&gt;&amp;rArr; 32&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;&amp;there4;&amp;nbsp;&lt;/span&gt;प्रति दर्जन ​केलों का घटा हुआ मूल्य&amp;nbsp;&lt;span style=&quot;&quot;&gt;32 है।&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/shortcut-trick-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Shortcut Trick&lt;/u&gt;&lt;/span&gt;&lt;strong&gt;&amp;nbsp;&lt;/strong&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;

&lt;p style=&quot;color: rgb(97, 106, 124); &quot;&gt;&lt;span style=&quot;color: rgb(37, 37, 37);  &quot;&gt;माना एक केले का मूल मूल्य 5x है, नया मूल्य 4x होगा (20% कम)&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;color: rgb(97, 106, 124); &quot;&gt;&lt;span style=&quot;color: rgb(37, 37, 37);  &quot;&gt;अब प्रश्न के अनुसार,&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;color: rgb(97, 106, 124); &quot;&gt;&amp;rArr;&amp;nbsp;&lt;span class=&quot;math-tex&quot;&gt;\(80\over 4x\)&lt;/span&gt;&amp;nbsp;-&amp;nbsp;&lt;span class=&quot;math-tex&quot;&gt;\(80\over 5x\)&lt;/span&gt;&amp;nbsp;= 6&lt;/p&gt;

&lt;p style=&quot;color: rgb(97, 106, 124); &quot;&gt;&amp;rArr;&amp;nbsp;&lt;span class=&quot;math-tex&quot;&gt;\({80 (5 - 4)}\over 4 \times 5 \times x\)&lt;/span&gt;&amp;nbsp;= 6&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&amp;rArr;&amp;nbsp;&lt;span class=&quot;math-tex&quot;&gt;\({80 (5 - 4)}\over 20 \times x\)&lt;/span&gt;&amp;nbsp;= 6&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;color: rgb(97, 106, 124);&quot;&gt;&amp;rArr;&amp;nbsp;&lt;span class=&quot;math-tex&quot;&gt;\(4\over x\)&lt;/span&gt;&amp;nbsp;= 6&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;color: rgb(97, 106, 124); &quot;&gt;&amp;rArr; x =&amp;nbsp;&lt;span class=&quot;math-tex&quot;&gt;\(2\over3\)&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;color: rgb(97, 106, 124); &quot;&gt;&lt;span style=&quot;color: rgb(37, 37, 37);  &quot;&gt;केले की नई कीमत है,&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;color: rgb(97, 106, 124); &quot;&gt;&amp;rArr; 4x = 4&amp;nbsp;&amp;times;&lt;span class=&quot;math-tex&quot;&gt;\(2\over3\)&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;color: rgb(97, 106, 124); &quot;&gt;&lt;span style=&quot;color: rgb(37, 37, 37);  &quot;&gt;कीमत प्रति दर्जन है&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;color: rgb(97, 106, 124); &quot;&gt;&amp;rArr; 4&amp;nbsp;&amp;times;&amp;nbsp;&lt;span class=&quot;math-tex&quot;&gt;\(2\over3\)&lt;/span&gt;&amp;nbsp;&amp;times; 12 = 32&lt;/p&gt;

en.value:
&lt;p&gt;&lt;strong&gt;Given:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;The simple interest on a sum of money at 10% per annum for 4 years is ₹3200.&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Concept used:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;S.I = (P &amp;times; T &amp;times; R)/100&lt;/p&gt;

&lt;p&gt;C.I = P(1 + R/100)&lt;sup&gt;T&lt;/sup&gt;&lt;/p&gt;

&lt;p&gt;Here,&lt;/p&gt;

&lt;p&gt;P = Sum&lt;/p&gt;

&lt;p&gt;R = Rate&lt;/p&gt;

&lt;p&gt;T = Time&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Calculation:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;Let the sum be P&lt;/p&gt;

&lt;p&gt;According to the question,&lt;/p&gt;

&lt;p&gt;3200 = (P &amp;times; 4 &amp;times; 10)/100&lt;/p&gt;

&lt;p&gt;&amp;rArr; P = 3200&amp;nbsp;&amp;times; (10/4)&lt;/p&gt;

&lt;p&gt;&amp;rArr; P = 8000&lt;/p&gt;

&lt;p&gt;So, sum is Rs. 8000&lt;/p&gt;

&lt;p&gt;Now,&lt;/p&gt;

&lt;p&gt;A = 8000(1 + 10/100)&lt;sup&gt;4&lt;/sup&gt;&lt;/p&gt;

&lt;p&gt;&amp;rArr;&amp;nbsp;&lt;span style=&quot;&quot;&gt;A = 8000(1 + 1/10)&lt;/span&gt;&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;4&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&amp;rArr;&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;&quot;&gt;A = 8000(11/10)&lt;/span&gt;&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;4&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&amp;rArr;&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;&quot;&gt;A = 8000(14641/10000)&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&amp;rArr;&amp;nbsp;A = 11712.80&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;&amp;there4; The amount (in ₹) of the same sum for the same period at the same rate of interest when the interest is compounded annually is 11712.80&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;

hn.value:
&lt;p&gt;&lt;span style=&quot;font-weight: 700; &quot;&gt;दिया गया है:&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;किसी धनराशि पर 10% प्रतिवर्ष की दर से 4 वर्षों का साधारण ब्याज ₹3200 है।&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;प्रयुक्त अवधारणा:&lt;/strong&gt;&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;&quot;&gt;साधारण ब्याज&lt;/span&gt; = (P &amp;times; T &amp;times; R)/100&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;&quot;&gt;चक्रवृद्धि&amp;nbsp;ब्याज&lt;/span&gt;&amp;nbsp;= P(1 + R/100)&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em;font-size:10.5px;&quot;&gt;T&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;यहाँ,&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;P&amp;nbsp;&lt;/span&gt;= राशि / मूलधन&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;R&amp;nbsp;&lt;/span&gt;= दर&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;T&amp;nbsp;&lt;/span&gt;= समय&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;गणना:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;मान लीजिए कि राशि, P है&lt;/p&gt;

&lt;p&gt;प्रश्न के अनुसार,&lt;/p&gt;

&lt;p&gt;3200 = (P &amp;times; 4 &amp;times; 10)/100&lt;/p&gt;

&lt;p&gt;&amp;rArr; P = 3200&amp;nbsp;&amp;times; (10/4)&lt;/p&gt;

&lt;p&gt;&amp;rArr; P = 8000&lt;/p&gt;

&lt;p&gt;इसलिए, राशि 8000 रुपये है&lt;/p&gt;

&lt;p&gt;अब,&lt;/p&gt;

&lt;p&gt;A = 8000(1 + 10/100)&lt;sup&gt;4&lt;/sup&gt;&lt;/p&gt;

&lt;p&gt;&amp;rArr;&amp;nbsp;&lt;span style=&quot;&quot;&gt;A = 8000(1 + 1/10)&lt;/span&gt;&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;4&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&amp;rArr;&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;&quot;&gt;A = 8000(11/10)&lt;/span&gt;&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;4&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&amp;rArr;&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;&quot;&gt;A = 8000(14641/10000)&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&amp;rArr;&amp;nbsp;A = 11712.80&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;&amp;there4; &lt;/span&gt;समान अवधि के लिए समान ब्याज दर पर उसी राशि का मिश्रधन (₹ में)&amp;nbsp;11712.80 होगा, जब ब्याज &lt;span style=&quot;&quot;&gt;चक्रवृद्धि&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;strong&gt;वार्षिक रूप से संयोजित होता है।&lt;/strong&gt;&lt;/p&gt;

en.value:
&lt;p&gt;&lt;strong&gt;Calculation:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;Let the integer be 6 + 2 = 8&lt;/p&gt;

&lt;p&gt;Substituting the value of n as 8 in the equation (n&lt;sup&gt;2&amp;nbsp;&lt;/sup&gt;+ n + 2)&amp;nbsp;&lt;/p&gt;

&lt;p&gt;&amp;rArr; &lt;span style=&quot;&quot;&gt;(8&lt;/span&gt;&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;&quot;&gt;+ 8&amp;nbsp;+ 2) = 74&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;Dividing 74 by 6, we get remainder as 2.&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;&amp;there4; Remainder for&amp;nbsp;&amp;nbsp;(n&lt;/span&gt;&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;&quot;&gt;+ n + 2)&amp;nbsp; when divided by 6 is 2.&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;

hn.value:
&lt;p&gt;&lt;strong&gt;गणना:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;मान लीजिए कि पूर्णांक 6 + 2 = 8 है&lt;/p&gt;

&lt;p&gt;समीकरण &lt;span style=&quot;&quot;&gt;(n&lt;/span&gt;&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;&quot;&gt;+ n + 2)&amp;nbsp;&lt;/span&gt;में n के मान को 8 के रूप में प्रतिस्थापित करने पर,&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&amp;rArr;&amp;nbsp;&lt;/span&gt;(&lt;span style=&quot;&quot;&gt;8&lt;/span&gt;&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;+ 8 + 2) = 74&lt;/p&gt;

&lt;p&gt;74 को 6 से भाग देने पर, शेषफल 2 प्राप्त होता है।&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;font-weight: 700; &quot;&gt;&amp;there4;&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;&quot;&gt;(n&lt;/span&gt;&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&lt;/span&gt;&lt;span style=&quot;&quot;&gt;&amp;nbsp;+ n + 2) को 6 से विभाजित करने पर शेषफल&amp;nbsp;&lt;/span&gt;2 है।&lt;/strong&gt;&lt;/p&gt;

en.value:
&lt;p&gt;&lt;strong&gt;Given data:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;Days in which X can complete the work = 46 days&lt;/p&gt;

&lt;p&gt;Days in which Y can complete the work = 92 days&lt;/p&gt;

&lt;p&gt;Days in which Z can complete the work = 23 days&lt;/p&gt;

&lt;p&gt;Days after which Y joined = 7 days&lt;/p&gt;

&lt;p&gt;Days after which Z joined = 8 days&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Formula used:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;Efficiency = Total work / Time taken to complete work individually&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Calculation:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;LCM of 23, 46, 92 = 92&lt;/p&gt;

&lt;p&gt;Assuming that the total work is 92 units.&lt;/p&gt;

&lt;p&gt;Efficiency of x-&lt;/p&gt;

&lt;p&gt;&amp;rArr;&amp;nbsp;&lt;span class=&quot;math-tex&quot;&gt;\(92\over 46\)&lt;/span&gt;&amp;nbsp;= 2 units of work/day&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;Efficiency of y-&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&amp;rArr;&amp;nbsp;&lt;span class=&quot;math-tex&quot;&gt;\(92\over 92\)&lt;/span&gt;&amp;nbsp;= 1&amp;nbsp;unit&amp;nbsp;of work/day&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;Efficiency of z-&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&amp;rArr;&amp;nbsp;&lt;span class=&quot;math-tex&quot;&gt;\(92\over 23\)&lt;/span&gt;&amp;nbsp;= 4&amp;nbsp;units of work/day&lt;/p&gt;

&lt;p&gt;Work done in 7 days by X working alone = 2 units&amp;nbsp;&amp;times; 7 = 14 units&lt;/p&gt;

&lt;p&gt;Work done by X and Y on 8th day =&amp;nbsp; (2 + 1)&amp;nbsp;&amp;times; 1 = 3 units&lt;/p&gt;

&lt;p&gt;Total work done until 8th day = 14 + 3 = 17 units&lt;/p&gt;

&lt;p&gt;Remaining work = 92 - 17 = 75 units&lt;/p&gt;

&lt;p&gt;Work done by X , Y and Z in one day = 2 + 1 + 4 = 7 units&lt;/p&gt;

&lt;p&gt;Total time taken =&amp;nbsp;&lt;span class=&quot;math-tex&quot;&gt;\(75\over 7\)&lt;/span&gt;&amp;nbsp;days&lt;/p&gt;

&lt;p&gt;Total days worked by Y =&amp;nbsp;&lt;span class=&quot;math-tex&quot;&gt;\(75\over 7\)&lt;/span&gt;&amp;nbsp;+ 1 =&amp;nbsp;&lt;span class=&quot;math-tex&quot;&gt;\(82\over 7\)&lt;/span&gt;&amp;nbsp;= 11&lt;span class=&quot;math-tex&quot;&gt;\(5\over 7\)&lt;/span&gt;&amp;nbsp;days.&lt;/p&gt;

&lt;p&gt;&amp;there4; &lt;strong&gt;Y worked for&amp;nbsp;&lt;/strong&gt;&lt;span style=&quot;&quot;&gt;11&lt;/span&gt;&lt;strong&gt;&lt;span class=&quot;math-tex&quot;&gt;\(5\over 7\)&lt;/span&gt;&lt;span style=&quot;&quot;&gt;&amp;nbsp;days.&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/shortcut-trick-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Shortcut Trick&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;Let the total work be 92 units.&lt;/p&gt;

&lt;p&gt;x = 46 days = 2 units/day&lt;/p&gt;

&lt;p&gt;y = 92 days = 1 unit/day&lt;/p&gt;

&lt;p&gt;z = 23 days = 4 units/day&lt;/p&gt;

&lt;p&gt;Let the work be completed in Q days.&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;According to the question,&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;2Q + 1&amp;nbsp;&amp;times; (Q - 7) + 4&amp;nbsp;&amp;times; (Q - 8) = 92&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&amp;rArr; 7Q - 39 = 92&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&amp;rArr; Q = 131/7&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&amp;rArr; Q - 7 = 131/7 - 7 (Subtracting 7 from both sides)&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&amp;rArr; Q - 7 =&amp;nbsp;&lt;span class=&quot;math-tex&quot;&gt;\(11\frac{5}{7}\)&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-weight: 700; &quot;&gt;&amp;there4; Y worked for&amp;nbsp;&lt;span class=&quot;math-tex&quot;&gt;\(11\frac{5}{7}\)&lt;/span&gt;&amp;nbsp;days.&lt;/span&gt;&lt;/p&gt;

hn.value:
&lt;p&gt;&lt;strong&gt;दी गई जानकारी:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;वह समय&amp;nbsp;जिसमें X कार्य को पूरा कर सकता है = 46 दिन&lt;/p&gt;

&lt;p&gt;वह &lt;span style=&quot;&quot;&gt;समय&lt;/span&gt; जिसमें Y कार्य को पूरा कर सकता है = 92 &lt;span style=&quot;&quot;&gt;दिन&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;वह &lt;span style=&quot;&quot;&gt;समय&lt;/span&gt; जिसमें Z कार्य को पूरा कर सकता है = 23 &lt;span style=&quot;&quot;&gt;दिन&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;जितने दिनों के बाद&amp;nbsp;Y सम्मिलित&amp;nbsp;हुआ = 7 &lt;span style=&quot;&quot;&gt;दिन&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;जितने दिनों के बाद&lt;/span&gt;&amp;nbsp;Z &lt;span style=&quot;&quot;&gt;सम्मिलित&lt;/span&gt;&lt;span style=&quot;&quot;&gt;&amp;nbsp;हुआ&lt;/span&gt; = 8 &lt;span style=&quot;&quot;&gt;दिन&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;प्रयुक्त सूत्र:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;दक्षता = कुल कार्य / व्यक्तिगत रूप से कार्य को पूरा करने में लिया गया समय&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;गणना:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;23, 46, 92 का लघुत्तम समापवर्त्य&amp;nbsp;= 92&lt;/p&gt;

&lt;p&gt;मान लीजिए कि कुल कार्य 92 इकाई है।&lt;/p&gt;

&lt;p&gt;x की दक्षता-&lt;/p&gt;

&lt;p&gt;&amp;rArr;&amp;nbsp;&lt;span class=&quot;math-tex&quot;&gt;\(92\over 46\)&lt;/span&gt;&amp;nbsp;= 2 &lt;span style=&quot;&quot;&gt;इकाई&amp;nbsp;&lt;/span&gt;कार्य/दिन&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;y की दक्षता-&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&amp;rArr;&amp;nbsp;&lt;span class=&quot;math-tex&quot;&gt;\(92\over 92\)&lt;/span&gt;&amp;nbsp;= 1&amp;nbsp;&lt;span style=&quot;&quot;&gt;इकाई&amp;nbsp;कार्य/दिन&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;z की दक्षता-&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&amp;rArr;&amp;nbsp;&lt;span class=&quot;math-tex&quot;&gt;\(92\over 23\)&lt;/span&gt;&amp;nbsp;= 4&amp;nbsp;&lt;span style=&quot;&quot;&gt;इकाई&amp;nbsp;कार्य/दिन&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;X द्वारा अकेले कार्य करते हुए 7 दिनों में किया गया कार्य = 2 &lt;span style=&quot;&quot;&gt;इकाई&amp;nbsp;&lt;/span&gt;&amp;times; 7 = 14 &lt;span style=&quot;&quot;&gt;इकाई&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;X और Y द्वारा 8वें दिन किया गया कार्य =&amp;nbsp; (2 + 1)&amp;nbsp;&amp;times; 1 = 3 &lt;span style=&quot;&quot;&gt;इकाई&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;8वें दिन तक किया गया कुल &lt;span style=&quot;&quot;&gt;कार्य&amp;nbsp;&lt;/span&gt;= 14 + 3 = 17 &lt;span style=&quot;&quot;&gt;इकाई&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;शेष कार्य = 92 - 17 = 75 &lt;span style=&quot;&quot;&gt;इकाई&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;X, Y और Z द्वारा एक दिन में किया गया कार्य = 2 + 1 + 4 = 7 &lt;span style=&quot;&quot;&gt;इकाई&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;लिया गया कुल समय =&amp;nbsp;&lt;span class=&quot;math-tex&quot;&gt;\(75\over 7\)&lt;/span&gt;&amp;nbsp;दिन&lt;/p&gt;

&lt;p&gt;Y द्वारा कार्य किए गए कुल दिन&amp;nbsp;=&amp;nbsp;&lt;span class=&quot;math-tex&quot;&gt;\(75\over 7\)&lt;/span&gt;&amp;nbsp;+ 1 =&amp;nbsp;&lt;span class=&quot;math-tex&quot;&gt;\(82\over 7\)&lt;/span&gt;&amp;nbsp;= 11&lt;span class=&quot;math-tex&quot;&gt;\(5\over 7\)&lt;/span&gt;&amp;nbsp;दिन&lt;/p&gt;

&lt;p&gt;&amp;there4; &lt;strong&gt;Y ने&amp;nbsp;&lt;/strong&gt;&lt;span style=&quot;&quot;&gt;11&lt;/span&gt;&lt;strong&gt;&lt;span class=&quot;math-tex&quot;&gt;\(5\over 7\)&lt;/span&gt;&lt;span style=&quot;&quot;&gt;&amp;nbsp;दिनों के लिए कार्य किया।&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;display: flex; gap: 6px; align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/shortcut-trick-image.png&quot; width=&quot;26px&quot; /&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;&lt;span style=&quot;font-size:20px;&quot;&gt;&lt;span style=&quot;vertical-align: middle; &quot;&gt;&lt;u&gt;Shortcut Trick&lt;/u&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;माना कि कुल कार्य 92 इकाई है।&lt;/p&gt;

&lt;p&gt;x = 46 दिन = 2 इकाई/दिन&lt;/p&gt;

&lt;p&gt;y = 92 दिन = 1 इकाई/दिन&lt;/p&gt;

&lt;p&gt;z = 23 दिन = 4 इकाई/दिन&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;माना कि कार्य&amp;nbsp;Q दिनों में पूरा हो जाता है।&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;प्रश्नानुसार,&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;2Q + 1&amp;nbsp;&amp;times; (Q - 7) + 4&amp;nbsp;&amp;times; (Q - 8) = 92&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&amp;rArr; 7Q - 39 = 92&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&amp;rArr; Q = 131/7&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&amp;rArr; Q - 7 = 131/7 - 7 (दोनों पक्षों से 7 घटाने पर)&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&amp;rArr; Q - 7 =&amp;nbsp;&lt;span class=&quot;math-tex&quot;&gt;\(11\frac{5}{7}\)&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;there4; &lt;strong&gt;Y ने&amp;nbsp;&lt;/strong&gt;&lt;/span&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;11&lt;/span&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;&lt;span class=&quot;math-tex&quot;&gt;\(5\over 7\)&lt;/span&gt;&amp;nbsp;दिनों के लिए कार्य किया।&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;

en.value:
&lt;p&gt;&lt;strong&gt;Given:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;PS &amp;perp; QR&lt;/p&gt;

&lt;p&gt;&amp;ang;Q = 66&amp;deg;&amp;nbsp;and&amp;nbsp;&amp;ang;R = 34&amp;deg;&lt;/p&gt;

&lt;p&gt;PT&amp;nbsp;is the bisector of &amp;ang;QPR&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Calculation:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;&lt;img alt=&quot;&quot; src=&quot;//storage.googleapis.com/tb-img/production/22/08/F3_Savita_SSC_26-8-22_D14.png&quot; style=&quot;height: 160px; width: 312px;&quot; /&gt;&lt;/p&gt;

&lt;p&gt;&amp;ang;QPR = 180&amp;deg; - 66&lt;span style=&quot;&quot;&gt;&amp;deg;&lt;/span&gt; - 34&lt;span style=&quot;&quot;&gt;&amp;deg;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&amp;rArr; 80&lt;span style=&quot;&quot;&gt;&amp;deg;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&amp;ang;QPT =&amp;nbsp;&amp;ang;TPR = 40&amp;deg;&amp;nbsp; &amp;nbsp; [As PT angle bisector]&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;In &amp;Delta; PTR&lt;/p&gt;

&lt;p&gt;&amp;ang;PTR&amp;nbsp;+&amp;nbsp;&amp;ang;PRT&amp;nbsp;+&amp;nbsp;&amp;ang;TPR = 180&amp;deg;&amp;nbsp;&lt;/p&gt;

&lt;p&gt;&amp;rArr;&amp;nbsp;&lt;span style=&quot;&quot;&gt;&amp;ang;PTR&amp;nbsp;&lt;/span&gt;=&amp;nbsp;180&amp;deg; - 34&amp;deg; - 40&amp;deg;&lt;/p&gt;

&lt;p&gt;&amp;rArr; &amp;ang;PTR = 106&amp;deg;&lt;/p&gt;

&lt;p&gt;Now,&lt;/p&gt;

&lt;p&gt;&amp;ang;PTS + &amp;ang;PTR = 180&amp;deg;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&amp;rArr; &amp;ang;PTS + 106&amp;deg;&amp;nbsp;= 180&amp;deg;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&amp;rArr; &amp;ang;PTS&lt;/span&gt;&lt;span style=&quot;&quot;&gt;&amp;nbsp;= 180&amp;deg; - 106&amp;deg;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&amp;rArr; &amp;ang;PTS&lt;/span&gt;&lt;span style=&quot;&quot;&gt;&amp;nbsp;= 74&amp;deg;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;So,&lt;/p&gt;

&lt;p&gt;&amp;ang;SPT = 180&amp;deg; - 90&amp;deg; - 74&amp;deg;&lt;/p&gt;

&lt;p&gt;&amp;rArr;&amp;nbsp;&lt;span style=&quot;&quot;&gt;&amp;ang;SPT = 16&amp;deg;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;&amp;there4; The measure of&amp;nbsp;&amp;ang;SPT is 16&amp;deg;.&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;

