&lt;p&gt;&amp;ang;QPR = 180&amp;deg; - 66&lt;span style=&quot;&quot;&gt;&amp;deg;&lt;/span&gt; - 34&lt;span style=&quot;&quot;&gt;&amp;deg;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&amp;rArr; 80&lt;span style=&quot;&quot;&gt;&amp;deg;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&amp;ang;QPT =&amp;nbsp;&amp;ang;TPR = 40&amp;deg;&amp;nbsp; &amp;nbsp; [चूँकि PT, कोण समद्विभाजक है]&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&amp;Delta; PTR में&lt;/p&gt;

&lt;p&gt;&amp;ang;PTR&amp;nbsp;+&amp;nbsp;&amp;ang;PRT&amp;nbsp;+&amp;nbsp;&amp;ang;TPR = 180&amp;deg;&amp;nbsp;&lt;/p&gt;

&lt;p&gt;&amp;rArr;&amp;nbsp;&lt;span style=&quot;&quot;&gt;&amp;ang;PTR&amp;nbsp;&lt;/span&gt;=&amp;nbsp;180&amp;deg; - 34&amp;deg; - 40&amp;deg;&lt;/p&gt;

&lt;p&gt;&amp;rArr; &amp;ang;PTR = 106&amp;deg;&lt;/p&gt;

&lt;p&gt;अब,&lt;/p&gt;

&lt;p&gt;&amp;ang;PTS + &amp;ang;PTR = 180&amp;deg;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&amp;rArr; &amp;ang;PTS + 106&amp;deg;&amp;nbsp;= 180&amp;deg;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&amp;rArr; &amp;ang;PTS&lt;/span&gt;&lt;span style=&quot;&quot;&gt;&amp;nbsp;= 180&amp;deg; - 106&amp;deg;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&amp;rArr; &amp;ang;PTS&lt;/span&gt;&lt;span style=&quot;&quot;&gt;&amp;nbsp;= 74&amp;deg;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;इसलिए,&lt;/p&gt;

&lt;p&gt;&amp;ang;SPT = 180&amp;deg; - 90&amp;deg; - 74&amp;deg;&lt;/p&gt;

&lt;p&gt;&amp;rArr;&amp;nbsp;&lt;span style=&quot;&quot;&gt;&amp;ang;SPT = 16&amp;deg;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;&amp;there4; &lt;/span&gt;&amp;ang;SPT का माप&amp;nbsp;&lt;span style=&quot;&quot;&gt;16&amp;deg; है।&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;

en.value:
&lt;p&gt;&lt;strong&gt;Given:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;A, B and C divide an amount of ₹10,500 amount themselves in the ratio 5 : 7 : 9, respectively.&amp;nbsp;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Calculation:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;Share of A = 10500&amp;nbsp;&amp;times; 5/21&lt;/p&gt;

&lt;p&gt;&amp;rArr; 2500&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;Share of B&amp;nbsp;= 10500&amp;nbsp;&amp;times; 7/21&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&amp;rArr; 3500&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;Share of C&amp;nbsp;= 10500&amp;nbsp;&amp;times; 9/21&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&amp;rArr; 4500&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;If each 500 more then the amount got by A, B and C = 3000, 4000, 5000&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;Ratio of new share = 3000 : 4000 : 5000 or 3 : 4 : 5&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&lt;strong&gt;&amp;there4; The ratio of the amount with A, B and C is 3 : 4 : 5.&lt;/strong&gt;&lt;/p&gt;

hn.value:
&lt;p&gt;&lt;span style=&quot;font-weight: 700; &quot;&gt;दिया गया है:&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;A, B और C, ₹10,500 की एक राशि को क्रमशः 5 : 7 : 9 के अनुपात में विभाजित करते हैं।&amp;nbsp;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-weight: 700; &quot;&gt;गणना:&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;A&amp;nbsp;का हिस्सा = 10500&amp;nbsp;&amp;times; 5/21&lt;/p&gt;

&lt;p&gt;&amp;rArr; 2500&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;B&amp;nbsp;&lt;span style=&quot;&quot;&gt;का हिस्सा&amp;nbsp;&lt;/span&gt;= 10500&amp;nbsp;&amp;times; 7/21&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&amp;rArr; 3500&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;C&amp;nbsp;&lt;span style=&quot;&quot;&gt;का हिस्सा&amp;nbsp;&lt;/span&gt;= 10500&amp;nbsp;&amp;times; 9/21&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&amp;rArr; 4500&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;यदि प्रत्येक को ₹500 अधिक प्राप्त होते हैं, तो A, B और C को प्राप्त राशियाँ = 3000, 4000, 5000&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;नए हिस्सों का अनुपात = 3000 : 4000 : 5000 या 3 : 4 : 5&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&lt;strong&gt;&amp;there4; A, B और C को प्राप्त राशियों का अनुपात&amp;nbsp;3 : 4 : 5 है।&lt;/strong&gt;&lt;/p&gt;

en.value:
&lt;p&gt;&lt;strong&gt;Given:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;A and B are two points on the same side of the ground, 50 meters apart.&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;The angles of elevation of these points to the top of a tree are 60&amp;deg;&amp;nbsp;and 30&lt;/span&gt;&lt;span style=&quot;&quot;&gt;&amp;deg;&lt;/span&gt;&lt;span style=&quot;&quot;&gt;, respectively.&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Concept used:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;&lt;img alt=&quot;&quot; src=&quot;//storage.googleapis.com/tb-img/production/22/08/Trigo.png&quot; style=&quot;width: 392px; height: 218px;&quot; /&gt;&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Calculation:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;&lt;img alt=&quot;&quot; src=&quot;//storage.googleapis.com/tb-img/production/22/08/F3_Savita_SSC_26-8-22_D15.png&quot; style=&quot;height: 164px; width: 174px;&quot; /&gt;&lt;/p&gt;

&lt;p&gt;Let the height of the tree be T and the distance between the foot of the tree to the point A be x&lt;/p&gt;

&lt;p&gt;Now,&lt;/p&gt;

&lt;p&gt;T/x = tan60&amp;deg;&lt;/p&gt;

&lt;p&gt;&amp;rArr; T/x =&amp;nbsp;&amp;radic;3&lt;/p&gt;

&lt;p&gt;&amp;rArr; T =&amp;nbsp;&amp;radic;3x&lt;/p&gt;

&lt;p&gt;Again,&lt;/p&gt;

&lt;p&gt;T/(x + 50) = tan30&amp;deg;&lt;/p&gt;

&lt;p&gt;&amp;rArr; T/(x + 50) = 1/&amp;radic;3&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&amp;rArr; T = (x + 50)/&amp;radic;3&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;Now,&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&amp;radic;3x = (x + 50)/&amp;radic;3&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&amp;rArr; 3x = x + 50&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&amp;rArr; 2x = 50&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&amp;rArr; x = 25&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;Now,&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;T/25 =&amp;nbsp;&amp;radic;3&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&amp;rArr; T = 25&amp;radic;3&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;So, height of the tree = 25&amp;radic;3 m&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;Now,&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;40% of the height of the tree = 25&amp;radic;3 &amp;times; 40%&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&amp;rArr; 10&amp;radic;3&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;&amp;there4;&amp;nbsp;40% of the height of the tree (in m) is 10&amp;radic;3.&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;

hn.value:
&lt;p&gt;&lt;span style=&quot;font-weight: 700; &quot;&gt;दिया गया है:&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;A और B एक जमीन, के एक ही तरफ 50 मीटर की दूरी पर दो बिंदु हैं।&lt;/p&gt;

&lt;p&gt;एक पेड़ के शीर्ष से इन बिंदुओं के उन्नयन कोण क्रमशः 60&amp;deg; और 30&amp;deg; हैं।&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;प्रयुक्त अवधारणा:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;&lt;img alt=&quot;&quot; src=&quot;//storage.googleapis.com/tb-img/production/22/08/Trigo.png&quot; style=&quot;width: 392px; height: 218px;&quot; /&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-weight: 700; &quot;&gt;गणना:&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;img alt=&quot;&quot; src=&quot;//storage.googleapis.com/tb-img/production/22/08/F3_Savita_SSC_26-8-22_D15.png&quot; style=&quot;height: 164px; width: 174px;&quot; /&gt;&lt;/p&gt;

&lt;p&gt;माना पेड़ की ऊँचाई T है और पेड़ के पाद से बिंदु A के बीच की दूरी x है&lt;/p&gt;

&lt;p&gt;अब,&lt;/p&gt;

&lt;p&gt;T/x = tan60&amp;deg;&lt;/p&gt;

&lt;p&gt;&amp;rArr; T/x =&amp;nbsp;&amp;radic;3&lt;/p&gt;

&lt;p&gt;&amp;rArr; T =&amp;nbsp;&amp;radic;3x&lt;/p&gt;

&lt;p&gt;पुनः,&lt;/p&gt;

&lt;p&gt;T/(x + 50) = tan30&amp;deg;&lt;/p&gt;

&lt;p&gt;&amp;rArr; T/(x + 50) = 1/&amp;radic;3&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&amp;rArr; T = (x + 50)/&amp;radic;3&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;अब,&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&amp;radic;3x = (x + 50)/&amp;radic;3&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&amp;rArr; 3x = x + 50&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&amp;rArr; 2x = 50&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&amp;rArr; x = 25&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;अब,&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;T/25 =&amp;nbsp;&amp;radic;3&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&amp;rArr; T = 25&amp;radic;3&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;इसलिए, &lt;/span&gt;पेड़ की ऊँचाई&amp;nbsp;&lt;span style=&quot;&quot;&gt;= 25&amp;radic;3 मीटर&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;अब,&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;पेड़ की ऊँचाई का 40%&amp;nbsp;&lt;span style=&quot;&quot;&gt;= 25&amp;radic;3 &amp;times; 40%&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&amp;rArr; 10&amp;radic;3&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;&amp;there4;&amp;nbsp;&lt;/span&gt;पेड़ की ऊँचाई का 40% (मीटर में)&amp;nbsp;&lt;span style=&quot;&quot;&gt;10&amp;radic;3 है।&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;

en.value:
&lt;p&gt;&lt;strong&gt;Given:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;Total surface area of a right pyramid, with base as a square of side 8 cm, is 208 cm&lt;/span&gt;&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em; font-size:10.5px;&quot;&gt;2&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Formula used:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;Total surface area = Lateral surface area + Area of the base&lt;/p&gt;

&lt;p&gt;Lateral surface area = 1/2 &amp;times; Perimeter of base &amp;times; slant height&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Calculation:&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;According to the question,&lt;/p&gt;

&lt;p&gt;208 =&amp;nbsp;&lt;span style=&quot;&quot;&gt;Lateral surface area + 8&lt;/span&gt;&lt;sup&gt;2&lt;/sup&gt;&lt;/p&gt;

&lt;p&gt;&amp;rArr; 208 - 64 =&amp;nbsp;&lt;span style=&quot;&quot;&gt;Lateral surface area&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&amp;rArr; 144 =&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;&quot;&gt;Lateral surface area&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;Again,&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;144 =&amp;nbsp;1/2 &amp;times; 4&amp;nbsp;&amp;times; 8 &amp;times; slant height&lt;/span&gt;&lt;/p&gt;

