&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt; &lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;table border=&quot;1&quot; cellpadding=&quot;1&quot; cellspacing=&quot;1&quot; style=&quot;width:350px;&quot;&gt;
	&lt;tbody&gt;
		&lt;tr&gt;
			&lt;td&gt;&lt;span style=&quot;&quot;&gt;डेमेट्रियस&lt;/span&gt;&lt;/td&gt;
			&lt;td&gt;
			&lt;ul&gt;
				&lt;li&gt;डेमेट्रियस प्रथम जिसे दमित्र भी कहा जाता है, एक &lt;span style=&quot;&quot;&gt;बैक्ट्रियन &lt;/span&gt;ग्रीक (इंडो-ग्रीक) राजा था जिसे पाली भाषा में योन और संस्कृत में &amp;quot;यवन&amp;quot; कहा गया। उसने बैक्ट्रिया से लेकर प्राचीन उत्तर-पश्चिमी भारत तक के क्षेत्र पर शासन किया।&lt;/li&gt;
				&lt;li&gt;वह &lt;span style=&quot;&quot;&gt;बैक्ट्रियन &lt;/span&gt;ग्रीक साम्राज्य के शासक यूथीडेमस &lt;span style=&quot;&quot;&gt;प्रथम&lt;/span&gt; का पुत्र था&lt;span style=&quot;&quot;&gt;।​&lt;/span&gt; उसने 200 ईसा पूर्व के आसपास &lt;span style=&quot;&quot;&gt;सत्ता संभाली &lt;/span&gt;और दक्षिणी अफगानिस्तान, ईरान, पाकिस्तान और भारत के बड़े भू-भाग पर कब्जा किया।​&lt;/li&gt;
			&lt;/ul&gt;
			&lt;/td&gt;
		&lt;/tr&gt;
		&lt;tr&gt;
			&lt;td&gt;सिकंदर&lt;/td&gt;
			&lt;td&gt;
			&lt;ul&gt;
				&lt;li&gt;सिकंदर प्राचीन यूनानी साम्राज्य &lt;span style=&quot;&quot;&gt;मकदूनियाँ &lt;/span&gt;का राजा था।&lt;/li&gt;
				&lt;li&gt;अपने पिता फिलिप द्वितीय के बाद 336 ईसा पूर्व में &lt;span style=&quot;&quot;&gt;20 वर्ष की आयु में &lt;/span&gt;वह सिंहासन पर बैठा और अपने शासन के अधिकांश समय वह पश्चिमी एशिया और मिस्र के विरुद्ध लंबे सैन्य अभियानों में लड़ता रहा।&lt;/li&gt;
				&lt;li&gt;&lt;span style=&quot;&quot;&gt;सिकंदर महान और पोरस के बीच 326 ईसा पूर्व &lt;/span&gt;हाइडस्पेस (झेलम) का युद्ध हुआ।&lt;/li&gt;
			&lt;/ul&gt;
			&lt;/td&gt;
		&lt;/tr&gt;
		&lt;tr&gt;
			&lt;td&gt;&lt;span style=&quot;&quot;&gt;यूक्रेटाइड्स&lt;/span&gt;&lt;/td&gt;
			&lt;td&gt;
			&lt;ul&gt;
				&lt;li&gt;यूक्रेटाइड्स प्रथम द ग्रेट सबसे महत्वपूर्ण &lt;span style=&quot;&quot;&gt;बैक्ट्रियन &lt;/span&gt;ग्रीक राजाओं में से एक था।&lt;/li&gt;
				&lt;li&gt;यूक्रेटिड्स ने यूथिडेमिड राजवंश को उखाड़ फेंका और डायोडोटिड्स की सत्ता बहाल की।&lt;/li&gt;
				&lt;li&gt;भारत में वह पूर्वी हेलेनिस्टिक और भारतीय शासकों के खिलाफ युद्ध लड़ा। उसने सिंध और ​​​​बारिगाज़ा के क्षेत्र पर कब्जा किया और अंत में मिनांडर से पराजित होने के बाद बैक्ट्रिया तक सीमित हो गया।&lt;/li&gt;
			&lt;/ul&gt;
			&lt;/td&gt;
		&lt;/tr&gt;
	&lt;/tbody&gt;
&lt;/table&gt;

